        merge("req-i2", "obs-1", 1, "站点B", "2.0", "备注").andExpect(status().isOk());
        merge("req-i2", "obs-1", 1, "站点B", "2.0", "备注")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));
